export fn swscale_create(
    src_w: c_int,
    src_h: c_int,
    src_fmt: c_int,
    dst_w: c_int,
    dst_h: c_int,
    dst_fmt: c_int,
    algo: c_int,
) ?*anyopaque {
    const ctx = std.heap.c_allocator.create(SwsContext) catch return null;
    ctx.* = .{
        .src_w = src_w,
        .src_h = src_h,
        .src_fmt = src_fmt,
        .dst_w = dst_w,
        .dst_h = dst_h,
        .dst_fmt = dst_fmt,
        .algo = algo,
    };
    return @ptrCast(ctx);
}

